import re


def expand(text, env):
    def replace(m):
        name, default = m.group(1), m.group(2)
        value = env.get(name, "")
        if default is not None and not value:
            return default
        return value
    return re.sub(r"\$\{(\w+)(?::-([^}]*))?\}", replace, text)

