def base_url(services, service, port, from_host):
    if not from_host:
        return f"http://{service}:{port}"
    for spec in services.get(service, {}).get("ports", []):
        host, container = spec.split(":")[-2:]
        if int(container) == port:
            return f"http://localhost:{host}"
    return None

